```dart
  Future<QuotaFetchResult> refresh(String providerId) {
    return _inFlight.putIfAbsent(providerId, () async {
      try {
        final result = await _fetchOnce(providerId);
        ...
      } finally {
        _inFlight.remove(providerId);
      }
    });
