    context,
    registry: registry,
    service: service,
    lastConnectionStore: lastConnectionStore,
    sessionKeysStore: sessionKeysStore,
    keychainStore: keychainStore,
    result: result,
    aiinModelsFetcher: aiinModelsFetcher,
    reauthenticateFor: reauthenticateFor,
  );
}

