+  final head = StringBuffer();
+  try {
+    socket.write(
+      'GET ${url.path}?${url.query} HTTP/1.1\r\n'
+      'Host: 127.0.0.1:${url.port}\r\n'
+      'Connection: close\r\n'
+      '\r\n',
+    );
+    await socket.flush();
+    await socket
