    ProviderPreset.aiin => 'aiin',
    ProviderPreset.openrouter => 'openrouter',
    ProviderPreset.ollamaCloud => 'ollama',
    ProviderPreset.gemini => 'google',
    ProviderPreset.dial => 'dial',
