  @override
  Widget build(BuildContext context) {
    final mark = _mark(presetKey);
    final tint = mark.$2;
    return Container(
      width: size,
      height: size,
      clipBehavior: Clip.antiAlias,
      decoration: BoxDecoration(
        color: mark.$3,
        borderRadius: BorderRadius.circular(size * 0.28),
      ),
